resource "aws_instance" "app" {
  # ... existing arguments ...

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"   # IMDSv2 only: a plain GET from an SSRF gets nothing
    http_put_response_hop_limit = 1            # tokens cannot be fetched from inside a container
  }

  root_block_device {
    volume_size = 16
    encrypted   = true
  }
}

resource "aws_iam_role_policy" "instance_least_privilege" {
  name = "${var.name}-instance"
  role = aws_iam_role.instance.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadOwnSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = aws_secretsmanager_secret.app.arn
      },
      {
        Sid      = "ShipLogs"
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
        Resource = "${aws_cloudwatch_log_group.host.arn}:*"
      }
    ]
  })
}

resource "aws_secretsmanager_secret" "app" {
  name                    = "${var.name}/app"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "app" {
  secret_id     = aws_secretsmanager_secret.app.id
  secret_string = jsonencode({
    grafana_password = var.grafana_password   # written once from your tfvars; rotate in the console later
    api_signing_key  = random_password.api_signing_key.result
  })
}

