# tests/security/test_infra_policy.py
import json
import subprocess

import pytest


@pytest.fixture(scope="module")
def plan():
    subprocess.run(["terraform", "-chdir=infra", "init", "-input=false", "-backend=false"], check=True, capture_output=True)
    subprocess.run(["terraform", "-chdir=infra", "plan", "-input=false", "-out=tfplan",
                    "-var=image=ghcr.io/example/x:latest", "-var=grafana_password=test", "-var=my_ip=203.0.113.9/32"],
                   check=True, capture_output=True)
    out = subprocess.run(["terraform", "-chdir=infra", "show", "-json", "tfplan"], check=True, capture_output=True, text=True).stdout
    return json.loads(out)


def resources(plan, rtype):
    return [r for r in plan["planned_values"]["root_module"]["resources"] if r["type"] == rtype]


def test_imdsv2_required(plan):
    inst = resources(plan, "aws_instance")[0]["values"]
    assert inst["metadata_options"][0]["http_tokens"] == "required"
    assert inst["metadata_options"][0]["http_put_response_hop_limit"] == 1


def test_root_volume_encrypted(plan):
    inst = resources(plan, "aws_instance")[0]["values"]
    assert inst["root_block_device"][0]["encrypted"] is True


def test_no_ssh_from_internet(plan):
    for sg in resources(plan, "aws_security_group"):
        for rule in sg["values"].get("ingress", []):
            if rule["from_port"] <= 22 <= rule["to_port"]:
                assert "0.0.0.0/0" not in rule["cidr_blocks"]


def test_instance_policy_has_no_wildcard_actions(plan):
    for pol in resources(plan, "aws_iam_role_policy"):
        doc = json.loads(pol["values"]["policy"])
        for st in doc["Statement"]:
            actions = st["Action"] if isinstance(st["Action"], list) else [st["Action"]]
            assert "*" not in actions and not any(a.endswith(":*") for a in actions)

- uses: sigstore/cosign-installer@v3
- name: Sign the image by digest (keyless, this workflow's identity)
  run: cosign sign --yes "${IMAGE}@${DIGEST}"
  env:
    IMAGE: ${{ env.IMAGE }}
    DIGEST: ${{ steps.build.outputs.digest }}

locals {
  detections = {
    ssh_key_change = {
      pattern   = "[..., key=ssh_keys]"              # auditd lines carrying the ssh_keys rule key
      threshold = 1
      summary   = "authorized_keys modified on the host"
    }
    root_command_burst = {
      pattern   = "[..., key=root_commands]"
      threshold = 20                                 # a deploy runs a handful; a human shell runs many
      summary   = "unusual volume of root commands"
    }
    admin_signature_failures = {
      pattern   = "{ $.event = \"auth.signature.invalid\" }"
      threshold = 10
      summary   = "repeated invalid signatures on /admin"
    }
  }
}

resource "aws_cloudwatch_log_metric_filter" "det" {
  for_each       = local.detections
  name           = "${var.name}-${each.key}"
  log_group_name = aws_cloudwatch_log_group.host.name
  pattern        = each.value.pattern
  metric_transformation {
    name      = each.key
    namespace = "${var.name}/security"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "det" {
  for_each            = local.detections
  alarm_name          = "${var.name}-${each.key}"
  alarm_description   = "${each.value.summary} — runbook: security/detections/${each.key}.md"
  namespace           = "${var.name}/security"
  metric_name         = each.key
  statistic           = "Sum"
  period              = 300
  evaluation_periods  = 1
  threshold           = each.value.threshold
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.security.arn]
}

resource "aws_sns_topic" "security" {
  name = "${var.name}-security-alerts"
}

resource "aws_sns_topic_subscription" "email" {
  topic_arn = aws_sns_topic.security.arn
  protocol  = "email"
  endpoint  = var.security_email
}
